sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_radius;
uniform float amzp_spacing;
uniform float amzp_twist;
uniform float amzp_rotSpeed;
uniform float amzp_flow;
uniform float amzp_shapeA;
uniform float amzp_shapeB;
uniform float amzp_shapeSize;
uniform float amzp_spin;
uniform float amzp_fillMode;
uniform float amzp_outlineW;
uniform float amzp_rungs;
uniform float amzp_rungStyle;
uniform float amzp_rungW;
uniform float amzp_rungOp;
uniform float amzp_spine;
uniform float amzp_spineSize;
uniform float amzp_depthScale;
uniform float amzp_depthFade;
uniform float amzp_colorMode;
layout(color) uniform half4 amzp_colA;
layout(color) uniform half4 amzp_colB;
uniform float amzp_hueSpeed;
uniform float amzp_glow;
uniform float amzp_glowSize;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        if (int(amzp_blendMode) == 4) return float4(min(b.rgb + f.rgb, float3(1.0)), max(b.a, f.a));
        return f + b * (1.0 - f.a);
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    float3 hue(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float sdBox(float2 p, float b) { float2 d = abs(p) - b; return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0); }
    float sdTri(float2 p) {
        p.y += 0.25;
        const float k = 1.7320508;
        p.x = abs(p.x) - 1.0;
        p.y = p.y + 1.0 / k;
        if (p.x + k * p.y > 0.0) p = float2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
        p.x -= clamp(p.x, -2.0, 0.0);
        return -length(p) * sign(p.y);
    }
    float sdHex(float2 p) {
        const float3 k = float3(-0.866025404, 0.5, 0.577350269);
        p = abs(p);
        p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
        p -= float2(clamp(p.x, -k.z * 0.9, k.z * 0.9), 0.9);
        return length(p) * sign(p.y);
    }
    float sdStar(float2 p) {
        const float2 k1 = float2(0.809016994, -0.587785252);
        const float2 k2 = float2(-k1.x, k1.y);
        p.x = abs(p.x);
        p -= 2.0 * max(dot(k1, p), 0.0) * k1;
        p -= 2.0 * max(dot(k2, p), 0.0) * k2;
        p.x = abs(p.x);
        p.y -= 1.0;
        float2 ba = 0.45 * float2(-k1.y, k1.x) - float2(0.0, 1.0);
        float h = clamp(dot(p, ba) / dot(ba, ba), 0.0, 1.0);
        return length(p - ba * h) * sign(p.y * ba.x - p.x * ba.y);
    }
    float sdPlus(float2 p) {
        p = abs(p);
        p = p.y > p.x ? p.yx : p;
        float2 q = p - float2(0.95, 0.32);
        float k = max(q.y, q.x);
        float2 w = k > 0.0 ? q : float2(0.32 - p.x, -k);
        return sign(k) * length(max(w, 0.0));
    }
    float sdShape(int s, float2 p) {
        if (s == 0) return length(p) - 0.9;
        if (s == 1) return sdBox(p, 0.75);
        if (s == 2) return sdTri(p * 1.05);
        if (s == 3) return (abs(p.x) + abs(p.y)) * 0.7071 - 0.68;
        if (s == 4) return sdHex(p);
        if (s == 5) return sdStar(p);
        return sdPlus(p);
    }
    float2 P; float T; float AA; float S1; float L; float RAD; float SP; float FO; float SZ; float OW; float GS;
    float4 C; float3 GL;
    float4 over(float4 top, float4 bot) { return top + bot * (1.0 - top.a); }
    float3 colAt(float ay, float strand) {
        float u = clamp(ay / max(L, 1.0) + 0.5, 0.0, 1.0);
        if (int(amzp_colorMode) == 0) return hue(fract(u * 0.85 + T * amzp_hueSpeed + strand * 0.08));
        if (int(amzp_colorMode) == 1) return mix(amzp_colA.rgb, amzp_colB.rgb, u);
        if (int(amzp_colorMode) == 2) return strand < 0.5 ? amzp_colA.rgb : amzp_colB.rgb;
        return amzp_colA.rgb;
    }
    float thetaAt(float ay) { return ay / max(L, 1.0) * amzp_twist * 6.28318531 + T * amzp_rotSpeed * 6.28318531; }
    void drawEl(float i, float strand, float stage) {
        float ay = i * SP + FO;
        float th = thetaAt(ay);
        float sg = strand < 0.5 ? 1.0 : -1.0;
        float x = RAD * sin(th) * sg;
        float z = cos(th) * sg;
        if (stage < 0.5 && z >= 0.0) return;
        if (stage > 0.5 && z < 0.0) return;
        float ds = max(1.0 + amzp_depthScale * z * 0.5, 0.05);
        float fade = 1.0 - amzp_depthFade * (0.5 - 0.5 * z);
        float sz = SZ * ds;
        float2 lp = advRot(P - float2(x, ay), -(radians(amzp_spin) * T + i * 0.7 + strand * 1.3)) / max(sz, 0.01);
        int st = strand < 0.5 ? int(amzp_shapeA) : int(amzp_shapeB);
        if (st == 7) st = int(mod(i + strand * 3.0, 7.0));
        float d = sdShape(st, lp) * sz;
        float cov;
        if (int(amzp_fillMode) == 1) cov = 1.0 - smoothstep(OW * 0.5 - AA, OW * 0.5 + AA, abs(d));
        else cov = 1.0 - smoothstep(-AA, AA, d);
        float3 col = colAt(ay, strand) * fade;
        C = over(float4(col * cov, cov), C);
        GL += col * amzp_glow * exp(-max(d, 0.0) / max(GS, 0.01)) * 0.5;
    }
    void drawRung(float i) {
        float ay = i * SP + FO;
        float th = thetaAt(ay);
        float x = RAD * sin(th);
        float dy = abs(P.y - ay);
        float xa = min(x, -x), xb = max(x, -x);
        float u = (P.x - xa) / max(xb - xa, 1e-3);
        if (u < -0.02 || u > 1.02) return;
        float w = amzp_rungW * S1;
        float m;
        if (int(amzp_rungStyle) == 0) {
            m = 1.0 - smoothstep(w * 0.5 - AA, w * 0.5 + AA, dy);
        } else {
            float n = max(floor((xb - xa) / max(SZ * 0.9, 1.0)), 1.0);
            float k = floor(u * n + 0.5) / n;
            float2 dp = P - float2(mix(xa, xb, k), ay);
            m = 1.0 - smoothstep(w - AA, w + AA, length(dp));
        }
        m *= clamp(1.0 - abs(u - 0.5) * 2.0 * 0.0, 0.0, 1.0) * amzp_rungOp;
        float3 col = mix(colAt(ay, 0.0), colAt(ay, 1.0), clamp(u, 0.0, 1.0)) * (1.0 - amzp_depthFade * 0.5);
        C = over(float4(col * m, m), C);
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = layerAt(uv);
        float ps = pxs();
        T = TT();
        float sc = max(amzp_scale * 2.0, 0.002);
        float2 ctr = 0.5 * W + float2(amzp_position.x, -amzp_position.y) * ps;
        P = advRot(uv * W - ctr, radians(amzp_angle)) / max(amzp_stretch, float2(0.01)) / sc;
        AA = 1.0 / sc;
        S1 = ps;
        L = max(W.x, W.y) / sc;
        RAD = amzp_radius * ps * 0.5;
        SP = max(amzp_spacing * ps, 1.0);
        FO = mod(T * amzp_flow * ps, SP);
        SZ = amzp_shapeSize * ps * 0.5;
        OW = amzp_outlineW * ps;
        GS = amzp_glowSize * ps;
        C = float4(0.0); GL = float3(0.0);
        float i0 = floor((P.y - FO) / SP + 0.5);
        for (int di = -3; di <= 3; di++) { float i = i0 + float(di); drawEl(i, 0.0, 0.0); drawEl(i, 1.0, 0.0); }
        if ((amzp_rungs>0.5)) { for (int di = -1; di <= 1; di++) drawRung(i0 + float(di)); }
        if ((amzp_spine>0.5)) {
            float hs = SP * 0.5;
            float k = floor((P.y - FO) / hs + 0.5);
            float2 dp = P - float2(0.0, k * hs + FO);
            float r = amzp_spineSize * ps * 0.5;
            float m = 1.0 - smoothstep(r - AA, r + AA, length(dp));
            float3 col = float3(0.92) * (1.0 - amzp_depthFade * 0.3);
            C = over(float4(col * m, m), C);
        }
        for (int di = -3; di <= 3; di++) { float i = i0 + float(di); drawEl(i, 0.0, 1.0); drawEl(i, 1.0, 1.0); }
        float3 g = GL * (1.0 - C.a);
        float4 G = float4(C.rgb + g, clamp(C.a + max(g.r, max(g.g, g.b)), 0.0, 1.0));
        G = clamp(G, 0.0, 1.0);
        G.rgb = min(G.rgb, float3(G.a));
        amzOutput = nmBlend(orig, nmGradMap(G));
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
